import test from 'node:test';
import assert from 'node:assert/strict';
import { getCustomer, listCustomers, validateCustomer, TIER_DISCOUNTS, normalizeId, mergeCustomers } from '../src/customers.js';

test('getCustomer finds a customer by id', () => {
  const r = getCustomer('C-003');
  assert.equal(r.ok, true);
  assert.equal(r.value.name, 'Kite & Co');
});

test('getCustomer reports an unknown id', () => {
  assert.deepEqual(getCustomer('C-999'), { ok: false, error: 'CUSTOMER_NOT_FOUND' });
});

test('every customer has a tier', () => {
  for (const c of listCustomers()) assert.ok(['gold', 'silver', 'standard'].includes(c.tier), c.id);
});

test('validateCustomer needs an id, a name and an email', () => {
  assert.equal(validateCustomer({ id: 'C-100', name: 'X', email: 'x@y.example' }).ok, true);
  assert.deepEqual(validateCustomer({ id: 'C-100', name: 'X', email: 'nope' }), { ok: false, error: 'CUSTOMER_INVALID' });
});

test('TIER_DISCOUNTS has correct values', () => {
  assert.equal(TIER_DISCOUNTS.gold, 5);
  assert.equal(TIER_DISCOUNTS.silver, 2.5);
  assert.equal(TIER_DISCOUNTS.standard, 0);
});

test('TIER_DISCOUNTS has all required tiers', () => {
  const tiersList = ['gold', 'silver', 'standard'];
  for (const tier of tiersList) {
    assert.ok(TIER_DISCOUNTS.hasOwnProperty(tier), `Missing tier: ${tier}`);
  }
});

test('normalizeId trims whitespace', () => {
  assert.equal(normalizeId('  C-001  '), 'C-001');
  assert.equal(normalizeId(' c-001 '), 'C-001');
});

test('normalizeId converts to uppercase', () => {
  assert.equal(normalizeId('c-001'), 'C-001');
  assert.equal(normalizeId('c-007'), 'C-007');
});

test('normalizeId handles mixed case with spaces', () => {
  assert.equal(normalizeId(' c-007 '), 'C-007');
  assert.equal(normalizeId('  C-003  '), 'C-003');
});

test('normalizeId on already normalized ID is idempotent', () => {
  assert.equal(normalizeId('C-001'), 'C-001');
  assert.equal(normalizeId(normalizeId('c-001')), 'C-001');
});

test('getCustomer finds customer with lowercase ID', () => {
  const r = getCustomer('c-001');
  assert.equal(r.ok, true);
  assert.equal(r.value.name, 'Northwind Studio');
});

test('getCustomer finds customer with mixed case ID', () => {
  const r = getCustomer('C-003');
  assert.equal(r.ok, true);
  assert.equal(r.value.name, 'Kite & Co');
});

test('getCustomer finds customer with spaces in ID', () => {
  const r = getCustomer(' c-001 ');
  assert.equal(r.ok, true);
  assert.equal(r.value.name, 'Northwind Studio');
});

